import { isoToUtcDate, utcDateToIso, type IsoDate } from './dates';

/** Day `dayOfMonth` of the month containing `iso`, clamped to the month's last day. */
export function dueDateInMonth(iso: IsoDate, dayOfMonth: number): IsoDate {
  const d = isoToUtcDate(iso);
  const year = d.getUTCFullYear();
  const month = d.getUTCMonth();
  const lastDay = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();
  return utcDateToIso(new Date(Date.UTC(year, month, Math.min(Math.max(dayOfMonth, 1), lastDay))));
}

/**
 * The expense date a recurring expense should have generated by `today`, or null when
 * this month's date is still ahead or falls before the recurring expense existed.
 */
export function recurringDueDate(today: IsoDate, dayOfMonth: number, startsOn: IsoDate): IsoDate | null {
  const due = dueDateInMonth(today, dayOfMonth);
  return due <= today && due >= startsOn ? due : null;
}

/** Next date a recurring expense will be generated (for display). */
export function nextRecurringDate(today: IsoDate, dayOfMonth: number): IsoDate {
  const thisMonth = dueDateInMonth(today, dayOfMonth);
  if (thisMonth > today) return thisMonth;
  const d = isoToUtcDate(today);
  const firstOfNext = utcDateToIso(new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 1)));
  return dueDateInMonth(firstOfNext, dayOfMonth);
}
